<script setup lang="ts">
import { computed, nextTick, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { getAccountList } from '@/api/account'
import { createProductBatch, getAccountGroups, getProductBatches, getProductMatrixDetail, getSavedProductFilters, newRequestId, previewProductBatch, queryProductMatrix, saveProductFilter, updateProductAutomation, updateProductLocalDetails, type AccountGroup, type MatrixProduct, type ProductBatchRequest, type ProductFilter } from '@/api/matrix'
import type { Account } from '@/types'
import { showError, showSuccess } from '@/utils'
import { useModalFocusTrap } from '@/composables/useModalFocusTrap'

type Detail = Record<string, any>
type EventDiffChange = { field: string; label?: string; before?: unknown; after?: unknown }
const route=useRoute(),router=useRouter(), loading=ref(false), loadError=ref(''), accounts=ref<Account[]>([]), groups=ref<AccountGroup[]>([]), products=ref<MatrixProduct[]>([]), total=ref(0), statusCounts=ref<Record<string,number>>({}), summary=ref<Record<string,any>>({}), notice=ref('')
const routeAccountId=Number(route.query.accountId)
const routeGroupId=Number(route.query.groupId),routePage=Number(route.query.page),routeWindow=Number(route.query.metricWindowDays)
const page=ref(Number.isSafeInteger(routePage)&&routePage>0?routePage:1)
const filter=reactive({search:String(route.query.search||''),accountId:Number.isSafeInteger(routeAccountId)&&routeAccountId>0?routeAccountId:undefined as number|undefined,groupId:Number.isSafeInteger(routeGroupId)&&routeGroupId>0?routeGroupId:undefined as number|undefined,statusBucket:String(route.query.statusBucket||'ALL'),source:String(route.query.source||''),publishChannel:String(route.query.publishChannel||''),metricWindowDays:([1,7,30].includes(routeWindow)?routeWindow:7) as 1|7|30})
const selectedKeys=ref<string[]>([]), excludedKeys=ref<string[]>([]), savedFilters=ref<Detail[]>([]), batches=ref<Detail[]>([]), selected=ref<Detail|null>(null), detailLoading=ref(false), detailDialog=ref(false), activeTab=ref<'basic'|'sku'|'marketing'|'metrics'|'timeline'>('basic')
const detailReturnScroll=ref(0)
const batchDialog=ref(false), batchLoading=ref(false), batchPreview=ref<Detail|null>(null), batch=reactive({operationType:'SYNC',selectionMode:'EXPLICIT_IDS' as 'EXPLICIT_IDS'|'FILTER_SNAPSHOT',value:'',speed:10,confirmationText:'',requestId:'',idempotencyKey:''})
const storePolishIntent=computed(()=>route.query.action==='POLISH_ALL'&&Boolean(filter.accountId)&&filter.statusBucket==='ON_SALE')
const imageFailures=reactive<Record<string,boolean>>({}), saveFilterDialog=ref(false), filterName=ref(''), editDialog=ref(false), editSaving=ref(false)
const editForm=reactive({title:'',supportPolicy:'',location:''})
useModalFocusTrap(batchDialog,()=>document.querySelector<HTMLElement>('.product-matrix .modal-card:not(.modal-card--small)'))
useModalFocusTrap(saveFilterDialog,()=>document.querySelector<HTMLElement>('.product-matrix .modal-card--small'))
useModalFocusTrap(detailDialog,()=>document.querySelector<HTMLElement>('.product-matrix .product-drawer'),()=>void closeDetail())
useModalFocusTrap(editDialog,()=>document.querySelector<HTMLElement>('.product-matrix .edit-local-dialog'))
const totalPages=computed(()=>Math.max(1,Math.ceil(total.value/20))), key=(p:MatrixProduct)=>`${p.accountId}:${p.goodsId}`, checked=(p:MatrixProduct)=>selectedKeys.value.includes(key(p))
const currentFilter=():ProductFilter=>({search:filter.search.trim()||undefined,accountIds:filter.accountId?[filter.accountId]:undefined,groupId:filter.groupId,statusBucket:filter.statusBucket,source:filter.source||undefined,publishChannel:filter.publishChannel||undefined,metricWindowDays:filter.metricWindowDays,page:page.value,pageSize:20})
const value=(v:unknown)=>v===null||v===undefined||v===''?'—':String(v), money=(v:unknown)=>v===null||v===undefined?'—':`¥ ${Number(v).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}`, time=(v:unknown)=>v?new Date(String(v)).toLocaleString('zh-CN'):'—'
const diffValue=(v:unknown)=>v===null||v===undefined||v===''?'（空）':typeof v==='boolean'?(v?'开启':'关闭'):typeof v==='object'?JSON.stringify(v):String(v)
const eventChanges=(event:Detail):EventDiffChange[]=>Object.entries(event.fieldDiff?.fields||{}).map(([field,change])=>({field,...(change as Omit<EventDiffChange,'field'>)}))
const labels:Record<string,string>={ALL:'全部',ON_SALE:'在售',SOLD:'已售出',OFF_SHELF:'已下架',OTHER:'其他',DRAFT:'草稿',FULL:'完整',EMPTY_VERIFIED:'已确认无规格',PARTIAL:'部分',UNSYNCED:'未同步',SUCCEEDED:'成功',FAILED:'失败',UNKNOWN:'结果未知',SYNC:'同步',POLISH:'擦亮',CHANGE_PRICE:'改价',CHANGE_STOCK:'改库存',DELETE:'删除'}, label=(v?:string)=>labels[v||'']||v||'未知', tone=(v?:string)=>['ON_SALE','FULL','EMPTY_VERIFIED','SUCCEEDED'].includes(v||'')?'good':['FAILED','UNKNOWN','DELETE'].includes(v||'')?'bad':['PARTIAL','OFF_SHELF'].includes(v||'')?'warn':'muted'
const productSourceText=(v?:string)=>({QA_MOCK:'隔离测试',PLATFORM_LIST_SYNC:'平台列表同步',PLATFORM_API:'平台接口',PLATFORM_WEB:'平台页面',LOCAL:'本地记录',MANUAL_IMPORT:'人工导入'}[v||'']||'其他来源')
const publishChannelText=(v?:string)=>({PLATFORM_API:'平台接口',PLATFORM_WEB:'平台页面',LOCAL_ONLY:'仅本地',MANUAL_IMPORT:'人工导入',QA_MOCK:'隔离测试'}[v||'']||'通道未记录')
const fulfillmentText=(v:unknown)=>{if(!v)return'未配置';if(typeof v!=='string')return'已配置履约模板';return v.includes('{deliveryContent}')?'固定卡密内容':v}
const cardPoolText=(v:unknown)=>{if(Array.isArray(v))return v.length?v.join('、'):'—';if(typeof v==='string'&&v.startsWith('[')){try{const parsed=JSON.parse(v);return Array.isArray(parsed)&&parsed.length?parsed.join('、'):'—'}catch{return v}}return v?String(v):'—'}
const productEventLabel=(v?:string)=>({LOCAL_DETAILS_EDIT:'本地商品资料已编辑',PRODUCT_LOCAL_EDIT:'本地商品资料已编辑',AUTOMATION_CONFIG_UPDATED:'自动化配置已更新',AUTOMATION_CONFIG_CHANGED:'自动化配置已更新',PRODUCT_AUTOMATION_UPDATE:'自动化配置已更新',PRODUCT_SYNC_STARTED:'商品同步开始',PRODUCT_SYNC_SUCCEEDED:'商品同步成功',PRODUCT_SYNC_FAILED:'商品同步失败',PRODUCT_SYNC_EXCEPTION:'商品同步异常',PRODUCT_PUBLISHED:'商品已发布',PRODUCT_PUBLISH:'商品发布',PRODUCT_PUBLISH_FAILED:'商品发布失败',PRODUCT_ON_SALE:'商品已上架',PRODUCT_OFF_SHELF:'商品已下架',PRICE_CHANGED:'价格已变更',STOCK_CHANGED:'库存已变更',POLISH_SUCCEEDED:'擦亮成功',BATCH_ITEM_SUCCEEDED:'批量子任务成功',BATCH_ITEM_FAILED:'批量子任务失败',BATCH_NOTIFICATION:'批量任务通知已生成',BATCH_CANCEL:'批量任务已取消',PRODUCT_BATCH_CANCEL:'批量任务已取消',PRODUCT_BATCH_CREATE:'批量任务已创建',PRODUCT_BATCH_RETRY:'批量失败项已重试',PRODUCT_BATCH_SUCCEEDED:'批量任务成功',PRODUCT_BATCH_PARTIAL:'批量任务部分成功',PRODUCT_BATCH_FAILED:'批量任务失败'}[v||'']||'其他商品事件')
const productOutcomeLabel=(v?:string)=>({LOCAL_SUCCESS:'本地处理成功',PLATFORM_CONFIRMED:'平台已确认',PLATFORM_REQUESTED:'已请求平台',SUCCEEDED:'成功',FAILED:'失败',UNKNOWN:'结果未知',SKIPPED:'已跳过',CANCELLED:'已取消'}[v||'']||'状态待核对')
const productSourceLabel=(v?:string)=>({LOCAL:'本地记录',PLATFORM_API:'平台接口',PLATFORM_WEB:'平台页面',WEBHOOK:'平台事件',SYSTEM:'系统任务',QA_MOCK:'隔离测试'}[v||'']||'其他来源')
const localizeProductDetail=(detail:Detail|null)=>{if(!detail)return detail;detail.timeline=(detail.timeline||[]).map((event:Detail)=>({...event,rawEventType:event.eventType,rawOutcomeState:event.outcomeState,rawDataSource:event.dataSource,eventType:productEventLabel(event.eventType),outcomeState:productOutcomeLabel(event.outcomeState),dataSource:productSourceLabel(event.dataSource)}));return detail}
const syncProductRoute=()=>router.replace({query:{...route.query,search:filter.search.trim()||undefined,accountId:filter.accountId?String(filter.accountId):undefined,groupId:filter.groupId?String(filter.groupId):undefined,statusBucket:filter.statusBucket==='ALL'?undefined:filter.statusBucket,source:filter.source||undefined,publishChannel:filter.publishChannel||undefined,metricWindowDays:filter.metricWindowDays===7?undefined:String(filter.metricWindowDays),page:page.value===1?undefined:String(page.value)}})
async function load(){loading.value=true;loadError.value='';void syncProductRoute();try{const r=await queryProductMatrix(currentFilter());products.value=r.data?.records||[];total.value=r.data?.total||0;statusCounts.value=r.data?.statusCounts||{};summary.value=r.data?.summary||{};notice.value=r.data?.dataNotice||''}catch(e:any){loadError.value=e.message||'商品矩阵加载失败'}finally{loading.value=false}}
async function loadSupporting(){const [a,g,f,b]=await Promise.allSettled([getAccountList(),getAccountGroups(),getSavedProductFilters(),getProductBatches()]);if(a.status==='fulfilled')accounts.value=a.value.data?.accounts||[];if(g.status==='fulfilled')groups.value=g.value.data||[];if(f.status==='fulfilled')savedFilters.value=f.value.data||[];if(b.status==='fulfilled')batches.value=b.value.data||[]}
function apply(){if(selectedKeys.value.length||excludedKeys.value.length){selectedKeys.value=[];excludedKeys.value=[];showSuccess('筛选已变化，原选择与排除项已清空，避免范围静默扩大')}page.value=1;void load()}
function toggle(p:MatrixProduct){selectedKeys.value=checked(p)?selectedKeys.value.filter(k=>k!==key(p)):[...selectedKeys.value,key(p)]}
function togglePage(){const keys=products.value.map(key),all=keys.every(k=>selectedKeys.value.includes(k));selectedKeys.value=all?selectedKeys.value.filter(k=>!keys.includes(k)):[...new Set([...selectedKeys.value,...keys])]}
const appScrollRoot=()=>document.querySelector<HTMLElement>('.app-main')
async function openDetail(p:Pick<MatrixProduct,'accountId'|'goodsId'>,fromDeepLink=false){if(!fromDeepLink)detailReturnScroll.value=appScrollRoot()?.scrollTop||0;detailDialog.value=true;detailLoading.value=true;const requestedTab=String(route.query.detailTab||'basic');activeTab.value=(['basic','sku','marketing','metrics','timeline'].includes(requestedTab)?requestedTab:'basic') as typeof activeTab.value;await router.replace({query:{...route.query,detailAccountId:String(p.accountId),goodsId:p.goodsId,detailTab:activeTab.value}});try{selected.value=localizeProductDetail((await getProductMatrixDetail(p.accountId,p.goodsId)).data||null)}catch(e:any){detailDialog.value=false;showError(e.message||'商品详情加载失败')}finally{detailLoading.value=false}}
async function closeDetail(){const scrollTop=detailReturnScroll.value;detailDialog.value=false;selected.value=null;await router.replace({query:{...route.query,detailAccountId:undefined,goodsId:undefined,detailTab:undefined}});await nextTick();appScrollRoot()?.scrollTo({top:scrollTop})}
function applySaved(item?:Detail){if(!item)return;const f=item.filter||{};Object.assign(filter,{search:f.search||'',accountId:f.accountIds?.[0],groupId:f.groupId,statusBucket:f.statusBucket||'ALL',source:f.source||'',publishChannel:f.publishChannel||'',metricWindowDays:f.metricWindowDays||7});apply()}
async function saveCurrentFilter(){if(!filterName.value.trim())return showError('请输入筛选器名称');await saveProductFilter({name:filterName.value.trim(),filter:currentFilter(),requestId:newRequestId('filter')});filterName.value='';saveFilterDialog.value=false;showSuccess('筛选器已保存');await loadSupporting()}
const selectedRefs=()=>selectedKeys.value.map(item=>{const [accountId,goodsId]=item.split(':');return{accountId:Number(accountId),goodsId:goodsId!}})
const excludedRefs=()=>excludedKeys.value.map(item=>{const [accountId,goodsId]=item.split(':');return{accountId:Number(accountId),goodsId:goodsId!}})
const batchRequest=(confirmationText=''):ProductBatchRequest=>({requestId:batch.requestId,idempotencyKey:batch.idempotencyKey,operationType:batch.operationType,selectionMode:batch.selectionMode,items:batch.selectionMode==='EXPLICIT_IDS'?selectedRefs():undefined,excludedItems:batch.selectionMode==='FILTER_SNAPSHOT'?excludedRefs():undefined,filter:batch.selectionMode==='FILTER_SNAPSHOT'?{...currentFilter(),page:1,pageSize:100}:undefined,operationParams:batch.operationType==='CHANGE_PRICE'?{price:batch.value}:batch.operationType==='CHANGE_STOCK'?{stock:batch.value}:{},maxOperationsPerMinute:batch.speed,confirmationText,previewToken:batchPreview.value?.previewToken})
function toggleExcluded(p:MatrixProduct){const k=key(p);excludedKeys.value=excludedKeys.value.includes(k)?excludedKeys.value.filter(item=>item!==k):[...excludedKeys.value,k];batchPreview.value=null}
function openBatch(){if(!selectedKeys.value.length&&batch.selectionMode==='EXPLICIT_IDS')return showError('请先选择商品，或改用符合筛选的跨页范围');batchPreview.value=null;batch.confirmationText='';batch.requestId=newRequestId('product-batch');batch.idempotencyKey=batch.requestId;batchDialog.value=true}
async function openStorePolish(){batch.operationType='POLISH';batch.selectionMode='FILTER_SNAPSHOT';openBatch();await runPreview()}
async function closeBatch(){batchDialog.value=false;batchPreview.value=null;batch.confirmationText='';if(route.query.action==='POLISH_ALL')await router.replace({query:{...route.query,action:undefined}})}
function validateBatchValue(){if(batch.operationType!=='CHANGE_PRICE')return true;const price=Number(batch.value);if(!Number.isFinite(price)||price<=0)return showError('新价格必须大于 0'),false;if(Math.abs(price*100-Math.round(price*100))>1e-6)return showError('新价格最多保留两位小数'),false;if(price>9999999.99)return showError('新价格不能超过 9999999.99'),false;return true}
async function runPreview(){batchPreview.value=null;if(!validateBatchValue())return;batchLoading.value=true;try{batchPreview.value=(await previewProductBatch(batchRequest())).data||null;if(batchPreview.value?.executionChannel==='QA_MOCK')showSuccess('隔离 QA Mock 已启用：任务不会触达闲鱼平台')}catch(e:any){showError(e.message||'批量预检失败')}finally{batchLoading.value=false}}
async function executeBatch(){if(!batchPreview.value||batch.confirmationText!==batchPreview.value.confirmationSummary)return showError('请输入完整确认文案');batchLoading.value=true;try{const r=await createProductBatch(batchRequest(batch.confirmationText));showSuccess(`任务已创建：${r.data?.batchId||r.data?.jobId}`);await closeBatch();selectedKeys.value=[];await Promise.all([load(),loadSupporting()])}finally{batchLoading.value=false}}
function startSingleAction(operationType:string){if(!selected.value)return;selectedKeys.value=[`${selected.value.basic.accountId}:${selected.value.basic.goodsId}`];batch.operationType=operationType;batch.selectionMode='EXPLICIT_IDS';openBatch()}
function setTab(tab:string){activeTab.value=tab as typeof activeTab.value;void router.replace({query:{...route.query,detailTab:activeTab.value}})}
async function copyGoodsId(){if(!selected.value)return;await window.navigator.clipboard.writeText(selected.value.basic.goodsId);showSuccess('商品 ID 已复制')}
async function refreshDetail(){if(!selected.value)return;detailLoading.value=true;try{selected.value=localizeProductDetail((await getProductMatrixDetail(selected.value.basic.accountId,selected.value.basic.goodsId)).data||selected.value);showSuccess('已重新读取本地缓存')}catch(e:any){showError(e.message||'缓存读取失败')}finally{detailLoading.value=false}}
async function saveAutomation(){if(!selected.value)return;const m=selected.value.marketing,r=await updateProductAutomation(selected.value.basic.accountId,selected.value.basic.goodsId,{autoDelivery:m.autoDeliveryEnabled,autoReply:m.autoReplyEnabled,autoRate:m.autoRateEnabled,autoPolish:m.autoPolishEnabled,humanTakeover:m.humanTakeoverEnabled,requestId:newRequestId('product-automation')});selected.value.marketing=r.data;showSuccess('自动化配置已保存并回读')}
function openLocalEdit(){if(!selected.value)return;Object.assign(editForm,{title:selected.value.basic.title||'',supportPolicy:selected.value.basic.supportPolicy||'',location:selected.value.basic.location||''});detailDialog.value=false;editDialog.value=true}
function closeLocalEdit(){editDialog.value=false;detailDialog.value=Boolean(selected.value)}
async function saveLocalEdit(){if(!selected.value||!editForm.title.trim())return showError('商品标题不能为空');editSaving.value=true;try{const r=await updateProductLocalDetails(selected.value.basic.accountId,selected.value.basic.goodsId,{...editForm,title:editForm.title.trim(),expectedVersion:selected.value.basic.rowVersion,requestId:newRequestId('product-local-edit')});selected.value=r.data||selected.value;closeLocalEdit();showSuccess('本地资料已保存；未向平台宣称同步');await load()}catch(e:any){showError(e.message||'本地资料保存失败')}finally{editSaving.value=false}}
onMounted(async()=>{await loadSupporting();await load();const accountId=Number(route.query.detailAccountId),goodsId=String(route.query.goodsId||'');if(Number.isSafeInteger(accountId)&&accountId>0&&goodsId)await openDetail({accountId,goodsId},true);else if(storePolishIntent.value)await openStorePolish()})
</script>

<template>
<main class="workbench product-matrix" :aria-busy="loading">
  <header class="workbench__header"><div><h1>商品矩阵</h1><p>跨店查看平台事实、同步证据、经营数据和可恢复任务。</p></div><div class="workbench__actions"><button class="workbench__btn" @click="router.push('/product-tasks')">任务中心</button><button class="workbench__btn" @click="router.push('/product-publish')">发布商品</button><button class="workbench__btn" @click="saveFilterDialog=true">保存筛选</button><button class="workbench__btn workbench__btn--primary" @click="openBatch">批量操作</button></div></header>
  <section class="product-matrix__metrics"><article><span>筛选结果</span><strong>{{ summary.productCount??'—' }}</strong><small>全量汇总</small></article><article><span>平均价格</span><strong>{{ money(summary.averagePrice) }}</strong><small>已知 {{ summary.knownPriceCount??'—' }} 件</small></article><article><span>已知库存</span><strong>{{ summary.knownStockTotal??'—' }}</strong><small>{{ summary.knownStockCount??'—' }} 件有证据</small></article><article><span>{{ filter.metricWindowDays }} 天曝光</span><strong>{{ summary.exposureCount??'未同步' }}</strong><small>{{ summary.metricDataDate||'无数据日期' }} · {{ label(summary.metricCoverageStatus) }}</small></article><article><span>指标同步</span><strong class="metric-time">{{ time(summary.metricSyncedAt) }}</strong><small>缺失不显示为 0</small></article></section>
  <div class="product-matrix__notice"><strong>数据说明</strong><span>{{ notice||'每行显示来源、覆盖度和同步时间。' }}</span></div>
  <section class="workbench__card product-matrix__panel">
    <div class="product-matrix__toolbar"><input v-model="filter.search" class="workbench__input" placeholder="商品 ID、标题或 outerId" @keyup.enter="apply"><select v-model="filter.accountId" class="workbench__select" @change="apply"><option :value="undefined">全部可见店铺</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{ a.accountNote||a.unb }}</option></select><select v-model="filter.groupId" class="workbench__select" @change="apply"><option :value="undefined">全部分组</option><option v-for="g in groups" :key="g.id" :value="g.id">{{ g.groupName }}</option></select><select v-model="filter.source" class="workbench__select" @change="apply"><option value="">全部来源</option><option value="PLATFORM_LIST_SYNC">平台列表同步</option><option value="PLATFORM_API">平台接口</option><option value="PLATFORM_WEB">平台页面</option><option value="LOCAL">本地</option></select><select v-model="filter.publishChannel" class="workbench__select" @change="apply"><option value="">全部通道</option><option value="PLATFORM_API">平台接口</option><option value="PLATFORM_WEB">平台页面</option><option value="LOCAL_ONLY">仅本地</option></select><select v-model="filter.metricWindowDays" class="workbench__select" @change="apply"><option :value="1">1 天</option><option :value="7">7 天</option><option :value="30">30 天</option></select><button class="workbench__btn" @click="apply">查询</button></div>
    <div class="product-matrix__tabs"><button v-for="s in ['ALL','ON_SALE','SOLD','OFF_SHELF','OTHER','DRAFT']" :key="s" :class="{active:filter.statusBucket===s}" @click="filter.statusBucket=s;apply()">{{ label(s) }} <span>{{ statusCounts[s]??'—' }}</span></button><select class="saved-filter" aria-label="已保存筛选器" @change="applySaved(savedFilters[Number(($event.target as HTMLSelectElement).value)])"><option value="">已保存筛选器</option><option v-for="(f,i) in savedFilters" :key="f.id" :value="i">{{ f.name }}</option></select></div>
    <div v-if="loading" class="product-matrix__state" role="status"><span class="product-matrix__spinner"></span><div><strong>正在更新商品</strong><small>旧列表与当前上下文仍保留。</small></div></div><div v-if="loadError" class="product-matrix__state product-matrix__state--error" role="alert"><div><strong>商品数据暂时无法读取</strong><small>{{ loadError }}</small></div><button class="workbench__btn" @click="load">重试</button></div>
    <div class="product-matrix__table"><table><thead><tr><th><input type="checkbox" :checked="products.length>0&&products.every(checked)" aria-label="选择当前页" @change="togglePage"></th><th>商品 / 店铺</th><th>入仓</th><th>价格 / 库存</th><th>状态</th><th>经营罗盘</th><th>来源</th><th>同步证据</th><th>操作</th></tr></thead><tbody><tr v-for="p in products" :key="key(p)" :class="{selected:checked(p)}" @click="openDetail(p)"><td><input type="checkbox" :checked="checked(p)" :aria-label="`选择 ${p.title}`" @click.stop @change="toggle(p)"></td><td><div class="product-cell"><img v-if="p.coverPic&&!imageFailures[key(p)]" :src="p.coverPic" alt="" @error="imageFailures[key(p)]=true"><div v-else class="product-cell__image">图</div><span><strong>{{ p.title||p.goodsId }}</strong><small>{{ p.accountNote||`店铺 ${p.accountId}` }} · {{ p.goodsId }}<template v-if="p.outerId"> · {{ p.outerId }}</template></small></span></div></td><td><span :class="['status',p.warehouseStatus==='CONFIGURED'?'good':'muted']">{{ p.warehouseStatus==='CONFIGURED'?'已配置':'未配置' }}</span><small>{{ p.fulfillmentMappingCount??0 }} 个映射</small></td><td><strong>{{ money(p.price) }}</strong><small>库存 {{ p.stock??'—' }} · SKU {{ p.skuCount??'—' }}</small></td><td><span :class="['status',tone(p.statusBucket)]">{{ label(p.statusBucket) }}</span></td><td><strong>{{ p.metric?.exposureCount??'未同步' }}</strong><small>{{ filter.metricWindowDays }} 天曝光 · {{ p.metric?.dataDate||'无数据日期' }}</small></td><td><strong>{{ productSourceText(p.source) }}</strong><small>{{ publishChannelText(p.publishChannel) }}</small></td><td><span :class="['status',tone(p.coverageStatus)]">{{ label(p.coverageStatus) }}</span><small>{{ time(p.lastSyncedTime) }}</small><em v-if="p.lastSyncErrorMessage">{{ p.lastSyncErrorMessage }}</em></td><td><button class="row-action" @click.stop="openDetail(p)">360° 详情</button></td></tr></tbody></table><div v-if="!loading&&!loadError&&!products.length" class="product-matrix__empty"><strong>{{ filter.search?'没有匹配商品':'当前范围尚无商品' }}</strong><p>{{ filter.search?'请调整关键词或清除筛选。':'先同步店铺商品，未同步数据不会显示成 0。' }}</p></div></div>
    <footer class="product-matrix__pagination"><span>已选 {{ selectedKeys.length }} 件 · 共 {{ total }} 件</span><div><button :disabled="loading||page<=1" @click="page--;load()">上一页</button><b>{{ page }} / {{ totalPages }}</b><button :disabled="loading||page>=totalPages" @click="page++;load()">下一页</button></div></footer>
  </section>
  <div v-if="selectedKeys.length" class="selection-dock"><div><strong>已选 {{ selectedKeys.length }} 件</strong><small>当前是逐项/当前页范围；跨页范围需在预检中明确选择。</small></div><button @click="selectedKeys=[]">清空</button><button class="workbench__btn--primary" @click="openBatch">批量操作</button></div>
  <section v-if="batches.length" class="workbench__card product-matrix__jobs"><div><h2>最近任务</h2><p>状态来自持久化任务。</p></div><div class="job-list"><article v-for="j in batches.slice(0,5)" :key="j.jobId" @click="router.push('/product-tasks')"><strong>{{ label(j.operationType) }} · {{ j.selectedCount }} 件</strong><span :class="['status',tone(j.status)]">{{ label(j.status) }}</span><small>成功 {{ j.successCount }} / 失败 {{ j.failedCount }} / 未知 {{ j.unknownCount }}</small></article></div></section>
  <div v-if="detailDialog" class="product-drawer__backdrop" @click.self="closeDetail"><aside class="product-drawer" role="dialog" aria-modal="true" aria-labelledby="product-title" tabindex="-1"><div v-if="detailLoading" class="product-matrix__empty">正在读取商品档案…</div><template v-else-if="selected"><header><div class="product-drawer__identity"><img v-if="selected.basic.coverPic" :src="selected.basic.coverPic" alt=""><div><h2 id="product-title">{{ selected.basic.title||selected.basic.goodsId }}</h2><p>{{ selected.basic.accountNote }} · {{ selected.basic.goodsId }} · {{ publishChannelText(selected.basic.publishChannel) }} · {{ productSourceText(selected.basic.source) }}</p></div></div><button aria-label="关闭" @click="closeDetail">×</button></header><nav role="tablist" aria-label="商品档案栏目"><button v-for="t in [{k:'basic',n:'基本信息'},{k:'sku',n:`SKU ${selected.skuEvidence?.verifiedCount??selected.skus?.length??'—'} / ${selected.skuEvidence?.declaredCount??'—'}`},{k:'marketing',n:'营销'},{k:'metrics',n:'数据罗盘'},{k:'timeline',n:`事件 ${selected.timeline?.length||0}`}]" :key="t.k" role="tab" :aria-selected="activeTab===t.k" :class="{active:activeTab===t.k}" @click="setTab(t.k)">{{ t.n }}</button></nav><div class="product-drawer__body">
    <template v-if="activeTab==='basic'"><div class="product-facts"><div><span>售价 / 原价</span><strong>{{ money(selected.basic.price) }} / {{ money(selected.basic.originalPrice) }}</strong></div><div><span>库存</span><strong>{{ value(selected.basic.stock) }}</strong></div><div><span>平台状态</span><strong>{{ label(selected.basic.statusBucket) }}</strong></div><div><span>同步覆盖</span><strong>{{ label(selected.basic.coverageStatus) }}</strong></div></div><section class="drawer-card"><h3>基本档案</h3><p>{{ selected.basic.detailJson||'描述未同步' }}</p><dl><div><dt>类目</dt><dd>{{ value(selected.basic.categoryName||selected.basic.categoryId) }}</dd></div><div><dt>业务 / 成色</dt><dd>{{ value(selected.basic.businessMode) }} / {{ value(selected.basic.conditionCode) }}</dd></div><div><dt>邮费</dt><dd>{{ selected.basic.shippingType||money(selected.basic.shippingFee) }}</dd></div><div><dt>所在地</dt><dd>{{ value(selected.basic.location) }}</dd></div><div><dt>支持政策</dt><dd>{{ value(selected.basic.supportPolicy) }}</dd></div><div><dt>创建 / 更新</dt><dd>{{ time(selected.basic.createdTime) }} / {{ time(selected.basic.updatedTime) }}</dd></div></dl></section><section class="drawer-card"><h3>订单摘要</h3><div v-if="selected.orderSummary.coverageStatus!=='UNSYNCED'" class="order-summary"><span>订单<strong>{{ selected.orderSummary.totalOrders }}</strong></span><span>已交付<strong>{{ selected.orderSummary.deliveredOrders??'—' }}</strong></span><span>退款相关<strong>{{ selected.orderSummary.refundOrders??'—' }}</strong></span><span>已知金额<strong>{{ money(selected.orderSummary.knownAmountTotal) }}</strong></span></div><p v-else>{{ selected.orderSummary.message }}</p><small>{{ label(selected.orderSummary.coverageStatus) }} · 最近订单 {{ time(selected.orderSummary.latestOrderTime) }} · 同步 {{ time(selected.orderSummary.latestSyncedTime) }}</small></section></template>
    <template v-else-if="activeTab==='sku'"><section class="drawer-card"><div :class="['sku-evidence',tone(selected.skuEvidence?.coverageStatus)]"><strong>{{ label(selected.skuEvidence?.coverageStatus) }}</strong><span>主档声明 {{ selected.skuEvidence?.declaredCount??'—' }} 个 · 已验证 {{ selected.skuEvidence?.verifiedCount??'—' }} 个</span><small>{{ selected.skuEvidence?.message }}</small></div><div v-if="selected.skus?.length" class="sku-list"><article v-for="sku in selected.skus" :key="sku.skuId||sku.skuKey"><strong>{{ sku.skuText||sku.skuKey }}</strong><span>{{ money(sku.price) }} · 库存 {{ sku.stock??'—' }}</span><small>平台状态 {{ sku.platformStatus?label(sku.platformStatus):'未同步' }} · {{ sku.syncDifference }}</small><small>履约 {{ fulfillmentText(sku.fulfillment?.deliveryTemplate) }} · 卡密池 {{ cardPoolText(sku.fulfillment?.cardPoolIds) }}</small></article></div><p v-else-if="selected.skuEvidence?.coverageStatus==='EMPTY_VERIFIED'">完整同步证据确认：该商品没有可拆分 SKU。</p><p v-else>SKU 子项尚无可验证数据，请重新同步商品详情；当前不能判定为 0 个规格。</p></section></template>
    <template v-else-if="activeTab==='marketing'"><section class="drawer-card"><h3>本地自动化</h3><div class="automation-switches"><label><input v-model="selected.marketing.autoDeliveryEnabled" type="checkbox">自动发货</label><label><input v-model="selected.marketing.autoReplyEnabled" type="checkbox">AI / 关键词回复</label><label><input v-model="selected.marketing.humanTakeoverEnabled" type="checkbox">人工接管</label><label><input v-model="selected.marketing.autoRateEnabled" type="checkbox">自动评价</label><label><input v-model="selected.marketing.autoPolishEnabled" type="checkbox">自动擦亮</label></div><button class="workbench__btn" @click="saveAutomation">保存并回读</button><h3>平台营销</h3><p>粉丝价 {{ value(selected.marketing.fanPrice) }} · 小刀 {{ value(selected.marketing.bargain) }} · 闲鱼币 {{ value(selected.marketing.coinDeduction) }}</p><small>粉丝价三档、协议授权、余额、让利成本与通道限制尚无可验证平台数据，因此不提供假配置入口。</small><div class="degraded-action">同步营销：平台营销适配器未接入，当前保持只读安全降级。</div></section></template>
    <template v-else-if="activeTab==='metrics'"><div v-for="(m,k) in selected.metrics" :key="k" class="metric-window"><header><strong>{{ k }}</strong><span :class="['status',tone(m.coverageStatus)]">{{ label(m.coverageStatus) }}</span></header><div><span>曝光<strong>{{ value(m.exposureCount) }}</strong></span><span>访客<strong>{{ value(m.visitorCount) }}</strong></span><span>点击<strong>{{ value(m.clickCount) }}</strong></span><span>收藏<strong>{{ value(m.favoriteCount) }}</strong></span><span>咨询<strong>{{ value(m.inquiryCount) }}</strong></span><span>支付<strong>{{ value(m.paidOrderCount) }}</strong></span></div><small>{{ m.sampleDays??'—' }} 天覆盖 · 数据日期 {{ m.dataDate||'未同步' }} · {{ time(m.syncedAt) }}；不同日期或未同步窗口不参与比较。</small></div><div class="degraded-action">同步罗盘：平台指标适配器未接入；当前仅读取各窗口缓存。</div></template>
    <template v-else><ol v-if="selected.timeline?.length" class="timeline"><li v-for="event in selected.timeline" :key="event.eventId"><i></i><div><strong>{{ event.eventType }}</strong><p>{{ event.outcomeState }} · {{ event.dataSource }} · {{ event.operatorUsername||'系统' }}</p><small>{{ time(event.createdTime) }} · 请求 {{ event.requestId||'—' }} · 任务 {{ event.jobId||'—' }} · 平台请求 {{ event.platformRequestId||'—' }}</small><div v-if="eventChanges(event).length" class="event-diff" aria-label="字段变更"><div v-for="change in eventChanges(event)" :key="change.field"><strong>{{ change.label||change.field }}</strong><span class="event-diff__before">{{ diffValue(change.before) }}</span><b aria-hidden="true">→</b><span class="event-diff__after">{{ diffValue(change.after) }}</span></div></div><p v-else-if="event.fieldDiff?.changedFieldCount===0" class="event-no-change">本次保存未产生字段变化</p><details><summary>脱敏高级详情与机器码</summary><pre>{{ JSON.stringify({eventType:event.rawEventType||event.eventType,outcomeState:event.rawOutcomeState||event.outcomeState,dataSource:event.rawDataSource||event.dataSource,error:event.errorMessage||null,rawSnapshotHash:event.rawSnapshotHash||null},null,2) }}</pre></details></div></li></ol><div v-else class="product-matrix__empty"><strong>尚无商品事件</strong><p>主动同步、Webhook 或本地编辑成功后会显示可关联的请求与任务证据。</p></div></template>
  </div><footer><button class="workbench__btn" @click="refreshDetail">读取缓存</button><button class="workbench__btn" @click="openLocalEdit">编辑本地资料</button><button class="workbench__btn" @click="startSingleAction('SYNC')">同步商品</button><button class="workbench__btn" disabled :title="selected.capabilities.CHANGE_PRICE?.reason||'当前平台改价适配器未验证，请使用批量预检查看安全降级原因'">改价（未接入）</button><button class="workbench__btn" disabled :title="selected.capabilities.CHANGE_STOCK?.reason||'当前平台改库存适配器未验证，请使用批量预检查看安全降级原因'">改库存（未接入）</button><button class="workbench__btn" :disabled="!selected.capabilities.POLISH.available" :title="selected.capabilities.POLISH.reason" @click="startSingleAction('POLISH')">擦亮</button><button class="workbench__btn" :disabled="!selected.capabilities.ON_SALE.available" :title="selected.capabilities.ON_SALE.reason" @click="startSingleAction('ON_SALE')">上架</button><button class="workbench__btn" :disabled="!selected.capabilities.OFF_SHELF.available" :title="selected.capabilities.OFF_SHELF.reason" @click="startSingleAction('OFF_SHELF')">下架</button><button class="workbench__btn danger" :disabled="!selected.capabilities.DELETE.available" :title="selected.capabilities.DELETE.reason" @click="startSingleAction('DELETE')">删除</button><button class="workbench__btn workbench__btn--primary" @click="copyGoodsId">复制 ID</button></footer></template></aside></div>
  <div v-if="editDialog" class="modal-backdrop" @click.self="closeLocalEdit"><section class="modal-card edit-local-dialog" role="dialog" aria-modal="true" aria-labelledby="edit-local-title"><header><div><h2 id="edit-local-title">编辑本地商品资料</h2><p>仅更新矩阵内的运营资料，不会冒充已同步到闲鱼平台。</p></div><button aria-label="关闭本地编辑" @click="closeLocalEdit">×</button></header><div class="modal-body edit-local-form"><label>商品标题<input v-model="editForm.title" class="workbench__input" maxlength="500" data-autofocus></label><label>所在地<input v-model="editForm.location" class="workbench__input" maxlength="255" placeholder="例如：上海"></label><label>支持政策<textarea v-model="editForm.supportPolicy" class="workbench__input" maxlength="1000" rows="4" placeholder="例如：七天使用期、售后群支持"></textarea></label><div class="local-only-note">保存后来源会标记为“本地已变更 / 部分覆盖”，下一次平台同步前不会显示为平台事实。</div></div><footer><button class="workbench__btn" @click="closeLocalEdit">取消</button><button class="workbench__btn workbench__btn--primary" :disabled="editSaving||!editForm.title.trim()" @click="saveLocalEdit">保存本地资料</button></footer></section></div>
  <div v-if="batchDialog" class="modal-backdrop" @click.self="closeBatch"><section class="modal-card" role="dialog" aria-modal="true" :aria-labelledby="storePolishIntent?'store-polish-title':'batch-title'"><header><div><h2 :id="storePolishIntent?'store-polish-title':'batch-title'">{{ storePolishIntent ? '全店立即擦亮预检' : '批量操作预检' }}</h2><p>{{ storePolishIntent ? `范围已锁定为店铺 ${filter.accountId} 的全部在售商品；这里只做预检，不会直接执行。` : '明确范围、冲突、速率和删除影响后再创建持久化任务。' }}</p></div><button aria-label="关闭" @click="closeBatch">×</button></header><div class="modal-body"><label>操作<select v-model="batch.operationType" class="workbench__select" :disabled="storePolishIntent"><option v-for="o in ['SYNC','POLISH','ON_SALE','OFF_SHELF','CHANGE_PRICE','CHANGE_STOCK','DELETE']" :key="o" :value="o">{{ label(o) }}</option></select></label><label>选择范围<select v-model="batch.selectionMode" class="workbench__select" :disabled="storePolishIntent" @change="batchPreview=null"><option value="EXPLICIT_IDS">已勾选 {{ selectedKeys.length }} 件</option><option value="FILTER_SNAPSHOT">符合筛选的跨页范围（最多 1000 件）</option></select></label><section v-if="batch.selectionMode==='FILTER_SNAPSHOT'" class="scope-exclusions"><header><strong>筛选快照：共 {{ total }} 件</strong><span>已明确排除 {{ excludedKeys.length }} 件</span></header><p>当前页可快速排除；关闭预检后可翻页继续添加，筛选一旦改变会清空全部排除项。</p><label v-for="p in products" :key="key(p)"><input type="checkbox" :checked="excludedKeys.includes(key(p))" @change="toggleExcluded(p)">排除 {{ p.accountNote||p.accountId }} · {{ p.title||p.goodsId }}</label></section><label v-if="['CHANGE_PRICE','CHANGE_STOCK'].includes(batch.operationType)">{{ batch.operationType==='CHANGE_PRICE'?'新价格':'新库存' }}<input v-model="batch.value" class="workbench__input" type="number" min="0"></label><label>每店每分钟上限<input v-model.number="batch.speed" class="workbench__input" type="number" min="1" max="30"></label><button class="workbench__btn" :disabled="batchLoading" @click="runPreview">{{ batchLoading ? '正在预检…' : '重新运行预检' }}</button><section v-if="batchPreview" class="batch-preview"><div><span>店铺</span><strong>{{ batchPreview.accountCount }}</strong></div><div><span>商品</span><strong>{{ batchPreview.selectedCount }}</strong></div><div><span>可执行</span><strong>{{ batchPreview.executableCount }}</strong></div><div><span>冲突</span><strong>{{ batchPreview.conflictCount }}</strong></div><p>{{ batchPreview.confirmationSummary }}</p><ul v-if="batchPreview.items?.some((i:Detail)=>!i.executable)"><li v-for="i in batchPreview.items.filter((x:Detail)=>!x.executable).slice(0,8)" :key="`${i.accountId}:${i.goodsId}`">{{ i.title||i.goodsId }}：{{ i.conflictMessage }}</li></ul><label>输入完整确认文案<input v-model="batch.confirmationText" class="workbench__input"></label></section></div><footer><button class="workbench__btn" @click="closeBatch">取消</button><button class="workbench__btn workbench__btn--primary" :disabled="!batchPreview||batch.confirmationText!==batchPreview.confirmationSummary||batchLoading" @click="executeBatch">{{ storePolishIntent ? '创建擦亮任务' : '创建任务' }}</button></footer></section></div>
  <div v-if="saveFilterDialog" class="modal-backdrop" @click.self="saveFilterDialog=false"><section class="modal-card modal-card--small" role="dialog" aria-modal="true"><header><div><h2>保存当前筛选</h2><p>保存条件，不复制商品。</p></div><button aria-label="关闭" @click="saveFilterDialog=false">×</button></header><div class="modal-body"><label>名称<input v-model="filterName" class="workbench__input" maxlength="80"></label></div><footer><button class="workbench__btn" @click="saveFilterDialog=false">取消</button><button class="workbench__btn workbench__btn--primary" @click="saveCurrentFilter">保存</button></footer></section></div>
</main>
</template>
