@media(max-width:767px){.product-matrix__toolbar{grid-template-columns:1fr}.order-summary{grid-template-columns:1fr 1fr}.product-drawer__backdrop{padding:0}.product-drawer{width:100vw;height:100dvh;min-height:0;border:0;border-radius:0}.product-drawer>footer{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));overflow:visible;padding:10px 12px max(10px,env(safe-area-inset-bottom))}.product-drawer>footer button{min-width:0;min-height:40px;padding:6px 5px;white-space:normal}.event-diff>div{grid-template-columns:1fr auto 1fr}.event-diff>div>strong{grid-column:1/-1}}
@media(max-height:520px){.product-drawer__backdrop{padding:0}.product-drawer{width:100vw;height:100dvh;min-height:0;border:0;border-radius:0}.product-drawer>header{flex:0 0 auto;align-items:center;padding:7px 12px}.product-drawer__identity img{width:34px;height:34px}.product-drawer h2{font-size:14px}.product-drawer__identity p{margin-top:2px;max-width:75vw;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.product-drawer>nav{flex:0 0 40px;min-height:40px}.product-drawer>nav button{min-height:40px;padding:7px 12px}.product-drawer__body{min-height:72px;padding:8px 10px}.product-drawer>footer{display:flex;flex:0 0 50px;justify-content:flex-start;overflow-x:auto;padding:6px 10px;scrollbar-width:thin}.product-drawer>footer button{min-width:max-content;min-height:36px;padding:5px 10px;white-space:nowrap}.product-facts{grid-template-columns:repeat(4,minmax(130px,1fr));overflow-x:auto}.product-facts div,.drawer-card,.metric-window{padding:10px}}
